{"version":3,"sources":["..\\scss\\profileShop.scss","profileShop.css","..\\scss\\_mixins.scss","..\\scss\\_variables.scss"],"names":[],"mappings":"AAGA;EACE,cAAA;ACFF;;ADKA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACFF;;ADKA;EACE,aAAA;EACA,uBAAA;EACA,8BAAA;EACA,SAAA;EACA,oBAAA;EACA,gCAAA;ACFF;;ADME;EEtBE,uCAAA;EACA,gBFsBoC;EErBpC,kBAAA;EACA,YCHW;EDIX,eFmB8B;EAC9B,mBAAA;ACCJ;;ADGA;EACE,eAAA;ACAF;ADCE;EACE,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,0BAAA;KAAA,uBAAA;ACCJ;;ADGA;EACE,aAAA;EACA,SAAA;EACA,mBAAA;EACA,mBAAA;ACAF;ADEE;EE5CE,uCAAA;EACA,gBF4CiC;EE3CjC,kBAAA;EACA,cCJQ;EDKR,eFyC2B;ACI/B;ADFI;EACE,UG/CO;AFmDb;;ADCA;EErDI,uCAAA;EACA,gBFqDkC;EEpDlC,kBAAA;EACA,YCHW;EDIX,eFkD4B;EAC9B,mBAAA;ACMF;ADJE;EACE,WAAA;EACA,gBAAA;ACMJ;;ADFA;EE/DI,uCAAA;EACA,gBF+DkC;EE9DlC,kBAAA;EACA,YCHW;EDIX,eF4D4B;EAC9B,mBAAA;ACSF;ADRE;EACE,WAAA;EACA,gBAAA;ACUJ;ADRI;EACE,YAAA;ACUN;;ADLA;EE5EI,uCAAA;EACA,gBF4E+B;EE3E/B,kBAAA;EACA,cCJQ;EDKR,eFyEyB;EAC3B,mBAAA;EACA,qBAAA;ACYF;ADVE;EACE,UGjFS;AF6Fb;;ADRA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACWF;ADVE;EE1FE,uCAAA;EACA,gBF0FoC;EEzFpC,kBAAA;EACA,YCHW;EDIX,eFuF8B;EAC9B,eAAA;ACgBJ;ADbE;EE/FE,uCAAA;EACA,gBF+FoC;EE9FpC,kBAAA;EACA,YCHW;EDIX,eF4F8B;EAC9B,sBAAA;ACmBJ;ADhBE;EACE,aAAA;EACA,uBAAA;EACA,SAAA;ACkBJ;ADhBI;EEzGA,uCAAA;EACA,gBFyGmC;EExGnC,kBAAA;EACA,cCJQ;EDKR,eFsG6B;ACsBjC;ADrBM;EACE,UG3GK;AFkIb","file":"profileShop.css","sourcesContent":["@import \"./variables\";\r\n@import \"./mixins\";\r\n\r\n.main__wrapper {\r\n  flex: 1 1 auto;\r\n}\r\n\r\n.main__shop-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n}\r\n\r\n.main__shop-list-item {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  justify-content: space-between;\r\n  gap: 15px;\r\n  padding-bottom: 10px;\r\n  border-bottom: 1px solid $gray; \r\n}\r\n\r\n.main__shop-list-item-text {\r\n  & h3 {\r\n    @include fonts($defaultColor, 18px, 600);\r\n    margin-bottom: 15px;\r\n  }\r\n}\r\n\r\n.main__shop-list-item-img {\r\n  flex: 0 0 200px;\r\n  & img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n    object-position: center;\r\n  }\r\n}\r\n\r\n.main__shop-list-item-edit {\r\n  display: flex;\r\n  gap: 10px;\r\n  align-items: center;\r\n  margin-bottom: 10px;\r\n\r\n  & a {\r\n    @include fonts($mainColor, 14px, 400);\r\n\r\n    &:hover {\r\n      color: $colorHover;\r\n    }\r\n  }\r\n}\r\n\r\n.main__shop-list-item-registration {\r\n  @include fonts($defaultColor, 16px, 400);\r\n  margin-bottom: 10px;\r\n\r\n  & span {\r\n    color: blue;\r\n    font-weight: 600;\r\n  }\r\n}\r\n\r\n.main__shop-list-item-active {\r\n  @include fonts($defaultColor, 16px, 400);\r\n  margin-bottom: 10px;\r\n  & span {\r\n    color: blue;\r\n    font-weight: 600;\r\n\r\n    & span {\r\n      color: green;\r\n    }\r\n  }\r\n}\r\n\r\n.main__shop-list-item-shop-link {\r\n  @include fonts($mainColor, 14px, 400);\r\n  margin-bottom: 15px;\r\n  display: inline-block;\r\n\r\n  &:hover {\r\n    color: $colorHover;\r\n  }\r\n}\r\n\r\n.main__shop-list-item-about {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n  & h4 {\r\n    @include fonts($defaultColor, 14px, 600);\r\n    flex: 0 0 100px;\r\n  }\r\n\r\n  & p {\r\n    @include fonts($defaultColor, 14px, 400);\r\n    word-break: break-word;\r\n  }\r\n\r\n  & li {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    gap: 10px;\r\n\r\n    & a {\r\n      @include fonts($mainColor, 14px, 400);\r\n      &:hover {\r\n        color: $colorHover;\r\n      }\r\n    }\r\n  }\r\n}",".main__wrapper {\n  flex: 1 1 auto;\n}\n\n.main__shop-list {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.main__shop-list-item {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 15px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.main__shop-list-item-text h3 {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n  margin-bottom: 15px;\n}\n\n.main__shop-list-item-img {\n  flex: 0 0 200px;\n}\n.main__shop-list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.main__shop-list-item-edit {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  margin-bottom: 10px;\n}\n.main__shop-list-item-edit a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n}\n.main__shop-list-item-edit a:hover {\n  color: red;\n}\n\n.main__shop-list-item-registration {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n.main__shop-list-item-registration span {\n  color: blue;\n  font-weight: 600;\n}\n\n.main__shop-list-item-active {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n.main__shop-list-item-active span {\n  color: blue;\n  font-weight: 600;\n}\n.main__shop-list-item-active span span {\n  color: green;\n}\n\n.main__shop-list-item-shop-link {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n  margin-bottom: 15px;\n  display: inline-block;\n}\n.main__shop-list-item-shop-link:hover {\n  color: red;\n}\n\n.main__shop-list-item-about {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n.main__shop-list-item-about h4 {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  flex: 0 0 100px;\n}\n.main__shop-list-item-about p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  word-break: break-word;\n}\n.main__shop-list-item-about li {\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n}\n.main__shop-list-item-about li a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n}\n.main__shop-list-item-about li a:hover {\n  color: red;\n}","@mixin fonts($color,$size,$weight) {\r\n    font-family: 'Trebuchet MS', sans-serif;\r\n    font-weight: $weight;\r\n    font-style: normal;\r\n    color: $color;\r\n    font-size: $size;\r\n}","$mainColor: #3077a0;\r\n$defaultColor: black;\r\n$colorHover: red;\r\n$headerTopBorder: #bdd4e2;\r\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\r\n$gray: #D4D4D4;\r\n$vipBg: #ff6163;\r\n$activeItem: #FFFFCA;\r\n$userSearchBg: #CFE6FE;\r\n$asideLinksColor: #307792;\r\n$asideExitColor: rgb(0, 128, 0);"]} #307792;\r\n$asideExitColor: rgb(0, 128, 0);"]}